 object : BroadcastReceiver() {
 override fun onReceive(context: Context, intent: Intent) {
 val receivedConversationId = intent.getStringExtra("conversationId")
 Log.d(TAG, "Received broadcast for conversation: $receivedConversationId")

 if (receivedConversationId == conversationId) {
 // Reload messages for the current conversation
 Log.d(TAG, "Reloading messages for current conversation: $conversationId")
 chatViewModel.loadMessages(conversationId)
 }
 // Always reload the list of conversations
 Log.d(TAG, "Reloading all conversations")
 chatViewModel.loadConversations()
 }
 }
 }

