 val receiver = object : BroadcastReceiver() {
 override fun onReceive(context: Context?, intent: Intent?) {
 val convId = intent?.getStringExtra("conversationId")
 Log.d(TAG, "[BroadcastReceiver] Reçu: conversationId=$convId, conversationId courant=$conversationId")
 if (convId == conversationId) {
 Log.d(TAG, "[BroadcastReceiver] Appel de chatViewModel.loadMessages($convId)")
 chatViewModel.loadMessages(convId)
 } else {
 Log.d(TAG, "[BroadcastReceiver] conversationId ne correspond pas, aucun reload (convId=$convId, attendu=$conversationId)")
 }
 }
 }
 val filter = IntentFilter("com.bluebridgeapp.NEW_CHAT_MESSAGE")
 // Use Android Tiramisu (API 33) check for RECEIVER_NOT_EXPORTED
 if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {
 context.registerReceiver(receiver, filter, Context.RECEIVER_NOT_EXPORTED)
 } else {
 ContextCompat.registerReceiver(
 context,
 receiver,
 filter,
 ContextCompat.RECEIVER_NOT_EXPORTED
 )
 }
 onDispose {
 Log.d(TAG, "[BroadcastReceiver] Unregister receiver")
 context.unregisterReceiver(receiver)
 }
